CREATE TABLE `page` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL,
  `name` varchar(255) NOT NULL,
  `background_image` varchar(500) DEFAULT NULL,
  `canvas_width` int DEFAULT '375',
  `canvas_height` int DEFAULT '812',
  `canvas_x` double DEFAULT NULL COMMENT '鍖哄潡鍦ㄦ棤闄愮敾甯冧笂鐨勪綅缃紙NULL=鑷姩甯冨眬锛�',
  `canvas_y` double DEFAULT NULL COMMENT '鍖哄潡鍦ㄦ棤闄愮敾甯冧笂鐨勪綅缃紙NULL=鑷姩甯冨眬锛�',
  `sort_order` int DEFAULT '0',
  `analyzed` tinyint DEFAULT '0' COMMENT '0=鏈狝I鍒嗘瀽 1=宸插垎鏋�',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `html_content` longtext COMMENT 'AI 鐢熸垚鐨勫畬鏁?HTML/CSS 椤甸潰',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`)
